#else
int cdecl main(int argc, char *argv[])
#endif
{
        init_header();
        init_setup();
        os_init_setup();
        os_process_arguments(argc, argv);
        init_buffer();
        init_err();
        init_memory();
        init_process();
        init_sound();
        os_init_screen();
        init_undo();
        z_restart();
        interpret();
        reset_screen();
        reset_memory();
        os_reset_screen();
        os_quit(EXIT_SUCCESS);
        return 0;
} /* main */
